def mark(fn):
 fn.__isabstractmethod__=True
 return fn
class C:
 @property
 @mark
 def field(self): return 7
print(C.field.__isabstractmethod__,C().field)

class Flag:
 def __init__(self,label,result): self.label=label; self.result=result
 @property
 def __isabstractmethod__(self):
  print(self.label)
  return self.result
p=property(Flag("get",False),Flag("set",False),Flag("del",True))
print(p.__isabstractmethod__)

